package com.example.eventflow.storage;

import java.util.Locale;

/** Helpers shared by the storage implementations. */
public final class StorageKeys {

    private StorageKeys() {
    }

    /** Media type derived from the key's extension (keys are generated by the server, never by users). */
    public static String contentTypeOf(String key) {
        String k = key.toLowerCase(Locale.ROOT);
        if (k.endsWith(".png")) return "image/png";
        if (k.endsWith(".jpg") || k.endsWith(".jpeg")) return "image/jpeg";
        if (k.endsWith(".webp")) return "image/webp";
        if (k.endsWith(".pdf")) return "application/pdf";
        return "application/octet-stream";
    }

    /** Rejects keys that could escape the storage root or are otherwise unexpected. */
    public static void validate(String key) {
        if (key == null || key.isBlank() || key.length() > 300 || key.startsWith("/") || key.contains("..")
                || key.contains("\\") || !key.matches("[A-Za-z0-9._/-]+")) {
            throw new StorageException("Invalid storage key");
        }
    }
}
